const $=s=>document.querySelector(s), canvas=$('#arena'),ctx=canvas.getContext('2d');
const species={mossling:{name:'Mossling',role:'Healer',color:'#87ba82',light:'#c5d690',dark:'#466c52',type:'heal',mark:'✚',rarity:'UNCOMMON',desc:'Restores team vitality'},emberfox:{name:'Emberfox',role:'Arcane striker',color:'#e68a5b',light:'#ffd18a',dark:'#9c4938',type:'magic',mark:'✦',rarity:'RARE',desc:'Burns foes with magic'},stoneback:{name:'Stoneback',role:'Guardian tank',color:'#a7a78a',light:'#e4d7a1',dark:'#55584e',type:'tank',mark:'⬟',rarity:'COMMON',desc:'Absorbs incoming damage'},sylphkin:{name:'Sylphkin',role:'Windweaver',color:'#81b9bd',light:'#c7eee2',dark:'#4e7181',type:'buff',mark:'⌁',rarity:'RARE',desc:'Raises allies’ power'},thornhorn:{name:'Thornhorn',role:'Wild bruiser',color:'#b8a06a',light:'#eadca0',dark:'#697347',type:'physical',mark:'✧',rarity:'COMMON',desc:'Crushing physical blows'},moonhare:{name:'Moonhare',role:'Dream mage',color:'#aab6d3',light:'#e6e5ff',dark:'#68738d',type:'magic',mark:'☾',rarity:'EPIC',desc:'Piercing lunar spells'},glimmerling:{name:'Glimmerling',role:'Dawn healer',color:'#dcad64',light:'#fff0af',dark:'#94714a',type:'heal',mark:'✦',rarity:'RARE',desc:'A little light goes far'},duskwing:{name:'Duskwing',role:'Sky sentinel',color:'#ae8fc4',light:'#e0c8ff',dark:'#63527e',type:'buff',mark:'⌁',rarity:'EPIC',desc:'Lifts the whole formation'}};
let owned=[{id:1,s:'mossling',level:2},{id:2,s:'emberfox',level:1},{id:3,s:'stoneback',level:1},{id:4,s:'sylphkin',level:1}],team=[],gold=42,wave=1,shop=[],fighting=false,speed=1,sorted=false,gameState={elapsed:0,round:1,effects:[],winner:null,units:[]},nextId=5;
function icon(s,size=56){let d=species[s];return `<svg class="pet-art" viewBox="0 0 64 72" aria-hidden="true"><ellipse cx="32" cy="66" rx="19" ry="4" fill="#070b0b" opacity=".55"/><path d="M14 53 Q7 58 12 62 Q20 63 23 55 M43 55 Q47 63 53 60 Q56 55 48 51" fill="${d.dark}"/><ellipse cx="32" cy="49" rx="19" ry="17" fill="${d.dark}"/><ellipse cx="31" cy="45" rx="16" ry="16" fill="${d.color}"/><ellipse cx="31" cy="50" rx="11" ry="9" fill="${d.light}" opacity=".78"/><path d="M18 34 Q12 18 20 20 Q27 22 28 33 M38 32 Q45 14 51 20 Q53 27 44 38" fill="${d.color}" stroke="${d.dark}" stroke-width="2"/><ellipse cx="31" cy="33" rx="15" ry="14" fill="${d.color}"/><ellipse cx="26" cy="34" rx="2.3" ry="3" fill="#192321"/><ellipse cx="38" cy="34" rx="2.3" ry="3" fill="#192321"/><circle cx="25.4" cy="33" r=".8" fill="white"/><circle cx="37.4" cy="33" r=".8" fill="white"/><path d="M29 40 Q32 42 35 40" fill="none" stroke="${d.dark}" stroke-width="1.5" stroke-linecap="round"/><path d="M19 30 Q31 23 44 30" fill="none" stroke="${d.light}" stroke-width="2" opacity=".6"/><circle cx="48" cy="16" r="5" fill="${d.light}" opacity=".8"/><text x="48" y="19" text-anchor="middle" font-size="7" fill="${d.dark}">${d.mark}</text></svg>`}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),1550)}
function petCard(p){let d=species[p.s],inTeam=team.includes(p.id);return `<div class="pet-card ${inTeam?'selected':''}" draggable="true" data-id="${p.id}">${icon(p.s)}<div class="pet-details"><div class="pet-name-line"><span class="pet-name">${d.name}</span><span class="rarity">${d.rarity}</span></div><div class="pet-role">${d.role}</div><div class="pet-stats"><span>❤ <b>${baseHp(p)}</b></span><span>✦ <b>${baseAtk(p)}</b></span><span>◈ <b>${p.level}</b></span></div></div><span class="pet-action">${d.type==='heal'?'HEALS':d.type==='tank'?'TANK':d.type==='buff'?'BUFF':d.type==='magic'?'MAGIC':'STRIKES'}</span><span class="pet-lvl">LV. ${p.level}</span></div>`}
function baseHp(p){return (p.s==='stoneback'?150:100)+p.level*12}function baseAtk(p){return (p.s==='stoneback'?14:p.s==='mossling'?17:p.s==='sylphkin'?18:p.s==='emberfox'?32:24)+p.level*4}
function render(){ $('#gold').textContent=gold;$('#wave').textContent=String(wave).padStart(2,'0');$('#teamCount').textContent=`${team.length} / 3`;$('#ownedCount').textContent=String(owned.length).padStart(2,'0');$('#foePower').textContent=250+wave*90;$('#roundNumber').textContent=gameState.round;$('#roster').innerHTML=(sorted?[...owned].sort((a,b)=>species[a.s].name.localeCompare(species[b.s].name)):owned).map(petCard).join('');$('#teamSlots').innerHTML=Array.from({length:3},(_,i)=>{let p=owned.find(x=>x.id===team[i]);if(!p)return `<div class="team-slot" data-slot="${i}"><div class="slot-empty"><strong>＋</strong>OPEN SLOT ${i+1}</div></div>`;let d=species[p.s];return `<div class="team-slot filled" data-slot="${i}">${icon(p.s)}<div class="slot-info"><b>${d.name}</b><small>${d.role} · LV.${p.level}</small></div><button class="remove-slot" data-remove="${i}" aria-label="Remove pet">×</button></div>`}).join('');$('#shopList').innerHTML=shop.map((s,i)=>{let d=species[s];return `<div class="shop-item ${s.sold?'sold':''}" data-buy="${i}">${icon(s)}<div class="shop-info"><div class="shop-name">${d.name}</div><div class="shop-desc">${d.role}</div><span class="shop-price">◈ ${price(s)}</span></div></div>`}).join('');$('.battle-status').innerHTML=fighting?'<i></i> COMPANIONS IN COMBAT':gameState.winner?`<i></i> ${gameState.winner==='win'?'VICTORY — ENCOUNTER CLEARED':'DEFEAT — REGROUP AND TRY AGAIN'}`:'<i></i> PREPARE YOUR FORMATION';$('.battle-status').classList.toggle('fighting',fighting);$('#battleText').textContent=fighting?'BATTLE IN PROGRESS':gameState.winner?gameState.winner==='win'?'CLAIM VICTORY':'TRY AGAIN':'START BATTLE';$('#battleBtn').disabled=fighting;$('#battleBtn').className='battle-btn'+(gameState.winner==='win'?' victory':gameState.winner==='lose'?' defeat':'');}
function price(s){return s.cost||18}function deal(){let pool=['thornhorn','glimmerling','moonhare','duskwing','emberfox','mossling','stoneback','sylphkin'];shop=Array.from({length:4},()=>{let s=pool[Math.floor(Math.random()*pool.length)];return {s,cost:s==='moonhare'||s==='duskwing'?28:s==='thornhorn'||s==='stoneback'?15:20}});render()}
function toggleTeam(id,slot){if(fighting)return;let idx=team.indexOf(id);if(idx>=0){team.splice(idx,1);if(slot!=null&&slot!==idx){let p=team.splice(idx,1)[0];team.splice(slot,0,p)}}else if(team.length<3){if(slot!=null&&slot<team.length)team.splice(slot,0,id);else team.push(id)}else{showToast('Your formation is full');return}render();draw()}

function buy(i){let item=shop[i];if(!item||item.sold)return;if(gold<price(item)){showToast('Not enough gold');return}if(owned.length>=12){showToast('Compendium is full');return}gold-=price(item);item.sold=true;owned.push({id:nextId++,s:item.s,level:1});showToast(`${species[item.s].name} joined your compendium!`);render()}
$('#roster').addEventListener('click',e=>{let c=e.target.closest('.pet-card');if(c)toggleTeam(+c.dataset.id)});$('#roster').addEventListener('dragstart',e=>{let c=e.target.closest('.pet-card');if(c)e.dataTransfer.setData('pet',c.dataset.id)});$('#teamSlots').addEventListener('click',e=>{let r=e.target.closest('[data-remove]');if(r){team.splice(+r.dataset.remove,1);render();draw()}});$('#teamSlots').addEventListener('dragover',e=>{if(e.target.closest('.team-slot')){e.preventDefault();e.target.closest('.team-slot').classList.add('drag-over')}});$('#teamSlots').addEventListener('dragleave',e=>e.target.closest('.team-slot')?.classList.remove('drag-over'));$('#teamSlots').addEventListener('drop',e=>{let sl=e.target.closest('.team-slot');if(sl){e.preventDefault();sl.classList.remove('drag-over');let id=+e.dataTransfer.getData('pet');if(id)toggleTeam(id,+sl.dataset.slot)}});$('#shopList').addEventListener('click',e=>{let c=e.target.closest('[data-buy]');if(c)buy(+c.dataset.buy)});$('#rerollBtn').onclick=()=>{if(gold<3){showToast('Need 3 gold to reroll');return}gold-=3;deal();showToast('The merchant found fresh stock')};$('#sortBtn').onclick=()=>{sorted=!sorted;render()};$('#marketTab').onclick=()=>{showToast('The travelling merchant is open below')};$('#upgradeBtn').onclick=()=>{let p=owned.find(x=>team.includes(x.id))||owned[0];if(!p){showToast('Recruit a companion first');return}if(gold<15){showToast('Need 15 gold to strengthen a bond');return}gold-=15;p.level++;showToast(`${species[p.s].name} reached level ${p.level}!`);render();draw()};$('#resetBtn').onclick=()=>{if(fighting)return;team=[];gameState.winner=null;render();draw()};$('#speedBtn').onclick=()=>{speed=speed===1?2:1;$('#speedBtn').innerHTML=`Ⅱ <span>${speed}× SPEED</span>`};$('#battleBtn').onclick=()=>{if(fighting)return;if(gameState.winner==='win'){gameState.winner=null;render();return}if(team.length===0){showToast('Choose at least one companion');return}startBattle()};
function startBattle(){fighting=true;gameState.winner=null;gameState.round=1;gameState.elapsed=0;gameState.effects=[];gameState.units=team.map(id=>{let p=owned.find(x=>x.id===id);return {p,hp:baseHp(p),max:baseHp(p),hit:0,heal:0}});gameState.enemyHp=260+wave*76;gameState.enemyMax=gameState.enemyHp;gameState.enemyHit=0;render();battleTick();clearInterval(gameState.timer);gameState.timer=setInterval(battleTick,1350/speed)}
function battleTick(){if(!fighting)return;gameState.round++;const allies=gameState.units.filter(x=>x.hp>0);if(!allies.length){finish('lose');return}let damage=0;let buff=allies.some(x=>x.p.s==='sylphkin'||x.p.s==='duskwing')?1.18:1;for(let u of allies){let s=u.p.s;if(s==='mossling'||s==='glimmerling'){let target=[...allies].sort((a,b)=>a.hp/a.max-b.hp/b.max)[0];let heal=28+u.p.level*6;target.hp=Math.min(target.max,target.hp+heal);target.heal=1;gameState.effects.push({type:'heal',x:target.p.s,y:0,t:45});continue}let atk=baseAtk(u.p)*buff;if(s==='stoneback')atk*=.8;if(s==='thornhorn')atk*=1.35;damage+=atk;u.hit=1;gameState.effects.push({type:s==='emberfox'||s==='moonhare'?'magic':'hit',t:30})}gameState.enemyHp-=damage;gameState.enemyHit=1;if(gameState.enemyHp<=0){finish('win');return}let enemyDmg=24+wave*4;let tank=allies.find(x=>x.p.s==='stoneback');let target=tank||allies[Math.floor(Math.random()*allies.length)];target.hp-=enemyDmg;target.hit=1;gameState.effects.push({type:'enemy',t:24});if(target.hp<=0){target.hp=0;showToast(`${species[target.p.s].name} needs a breather`)}gameState.round++;render();if(gameState.units.every(x=>x.hp<=0)||gameState.round>11)finish('lose');draw()}
function finish(result){fighting=false;clearInterval(gameState.timer);gameState.winner=result;if(result==='win'){let reward=12+wave*2;gold+=reward;showToast(`VICTORY! +${reward} GOLD`);wave++;}else showToast('Your party was overwhelmed. Try a new formation.');render();draw()}
// Isometric arena rendered in canvas: layered terrain, toy-like companions, foliage and animated battle effects.
let W=0,H=0,dpr=1,clock=0;
function resize(){let r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){if(!W||!H)return;clock+=.016;ctx.clearRect(0,0,W,H);let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#394d43');sky.addColorStop(.42,'#52634d');sky.addColorStop(1,'#243b32');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let glow=ctx.createRadialGradient(W*.52,H*.13,0,W*.52,H*.13,W*.42);glow.addColorStop(0,'#ddc47d50');glow.addColorStop(1,'#ddc47d00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.7);
// distant forest layers
for(let layer=0;layer<3;layer++){let base=H*(.33+layer*.065),color=['#354b3c','#293e34','#22382f'][layer];ctx.fillStyle=color;for(let i=-1;i<13;i++){let x=i*W/11+(layer*27%35),rh=H*(.14+((i*37+layer*19)%53)/180),rw=W*.055;ctx.beginPath();ctx.moveTo(x-rw,base);ctx.lineTo(x-rw*.72,base-rh*.48);ctx.lineTo(x-rw*.36,base-rh*.4);ctx.lineTo(x,base-rh);ctx.lineTo(x+rw*.23,base-rh*.44);ctx.lineTo(x+rw*.72,base-rh*.5);ctx.lineTo(x+rw,base);ctx.closePath();ctx.fill()}}
// distant stream and arena floor
ctx.fillStyle='#84946c';ctx.beginPath();ctx.moveTo(W*.42,H*.39);ctx.bezierCurveTo(W*.51,H*.35,W*.53,H*.41,W*.61,H*.39);ctx.bezierCurveTo(W*.59,H*.54,W*.51,H*.56,W*.44,H*.49);ctx.closePath();ctx.fill();ctx.fillStyle='#849871';ctx.beginPath();ctx.ellipse(W*.5,H*.75,W*.44,H*.245,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#bac18a40';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(W*.5,H*.75,W*.44,H*.245,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#a89d6d';ctx.beginPath();ctx.ellipse(W*.5,H*.74,W*.395,H*.197,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#68784e';ctx.beginPath();ctx.ellipse(W*.5,H*.74,W*.375,H*.182,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#798457';ctx.beginPath();ctx.ellipse(W*.5,H*.75,W*.345,H*.156,0,0,Math.PI*2);ctx.fill();
// stone inlays and little blossoms
for(let i=0;i<16;i++){let a=i*Math.PI/8,x=W*.5+Math.cos(a)*W*.385,y=H*.75+Math.sin(a)*H*.186;ctx.fillStyle=i%2?'#c1b481':'#89936a';ctx.beginPath();ctx.ellipse(x,y,W*.009,H*.009,0,0,Math.PI*2);ctx.fill()}for(let i=0;i<32;i++){let x=((i*73+39)%997)/997*W,y=H*(.36+((i*47)%55)/100);if(y>H*.61&&Math.abs((x-W*.5)/(W*.39))<1){ctx.fillStyle=i%3?'#d8c86b':'#d7b6a0';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(x,y,1.3,0,7);ctx.fill();ctx.globalAlpha=1}}
// edge boulders and foliage
for(let i=0;i<11;i++){let x=(i/10)*W,y=H*(.58+(i%3)*.07),r=W*(.012+(i%4)*.003);ctx.fillStyle=i%2?'#58674a':'#6d7954';ctx.beginPath();ctx.ellipse(x,y,r*1.5,r*.7,0,0,7);ctx.fill();ctx.fillStyle='#849261';ctx.beginPath();ctx.ellipse(x-r*.5,y-r*.25,r*.65,r*.5,0,0,7);ctx.fill()}
// battle creatures, ally and foe ranks
const ally=team.map(id=>{let p=owned.find(x=>x.id===id);return p&&{p,unit:gameState.units.find(u=>u.p.id===id)}}).filter(Boolean);let enemies=[{s:'thornhorn',hp:gameState.enemyHp||260+wave*76,max:gameState.enemyMax||260+wave*76,chief:true},{s:'duskwing',hp:gameState.enemyHp||260+wave*76,max:gameState.enemyMax||260+wave*76},{s:'moonhare',hp:gameState.enemyHp||260+wave*76,max:gameState.enemyMax||260+wave*76}];let allyX=[.27,.39,.33],enemyX=[.70,.79,.67];ally.forEach((a,i)=>drawCreature(a.p.s,W*allyX[i],H*(.66+(i===1?.06:0)),Math.min(1.05,W/850),true,a.unit));enemies.forEach((e,i)=>drawCreature(e.s,W*enemyX[i],H*(.57+(i===1?.06:0)),Math.min(1,W/850),false,{hp:e.hp,max:e.max,hit:gameState.enemyHit||0},i===0));
if(fighting){ctx.save();ctx.globalAlpha=.28+Math.sin(clock*4)*.08;ctx.strokeStyle='#ffdc8c';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(W*.49,H*.73,W*.23,H*.085,0,0,7);ctx.stroke();ctx.restore()}requestAnimationFrame(draw)}

function drawCreature(s,x,y,scale,isAlly,unit,big=false){let d=species[s],bob=Math.sin(clock*2.7+(x*0.02))*(fighting?3:1.6),sz=scale*(big?1.18:1),hurt=unit?.hit>0;ctx.save();ctx.translate(x,y+bob);ctx.scale(sz,sz);if(hurt){ctx.translate(Math.sin(clock*35)*2,0);if(unit)unit.hit=Math.max(0,unit.hit-.035)}
// soft foot shadow
ctx.fillStyle='#11191167';ctx.beginPath();ctx.ellipse(0,0,29,8,0,0,Math.PI*2);ctx.fill();let g=ctx.createRadialGradient(-9,-42,2,0,-23,34);g.addColorStop(0,d.light);g.addColorStop(.55,d.color);g.addColorStop(1,d.dark);
// tail
ctx.strokeStyle=d.dark;ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-15,-21);ctx.quadraticCurveTo(-31,-22,-29,-38);ctx.stroke();ctx.fillStyle=d.light;ctx.beginPath();ctx.arc(-29,-38,3,0,7);ctx.fill();
// feet and body
ctx.fillStyle=d.dark;for(let i=0;i<4;i++){let px=(i%2?13:-13),py=i<2?-6:0;rr(px-5,py-12,10,16,5);ctx.fill()}ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,-24,22,22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=d.light;ctx.globalAlpha=.64;ctx.beginPath();ctx.ellipse(0,-19,12,12,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// ears and decorative creature silhouette
ctx.fillStyle=d.dark;if(s==='moonhare'){ctx.beginPath();ctx.ellipse(-10,-68,6,19,-.22,0,Math.PI*2);ctx.ellipse(10,-67,6,20,.17,0,Math.PI*2);ctx.fill()}else if(s==='sylphkin'||s==='duskwing'){ctx.beginPath();ctx.moveTo(-15,-47);ctx.quadraticCurveTo(-42,-72,-34,-43);ctx.quadraticCurveTo(-24,-39,-16,-35);ctx.moveTo(15,-46);ctx.quadraticCurveTo(41,-75,34,-42);ctx.quadraticCurveTo(24,-39,16,-35);ctx.fill()}else{ctx.beginPath();ctx.moveTo(-17,-44);ctx.lineTo(-23,-62);ctx.quadraticCurveTo(-14,-63,-8,-47);ctx.moveTo(13,-46);ctx.lineTo(23,-61);ctx.quadraticCurveTo(28,-52,19,-41);ctx.fill()}
ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,-45,17,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=d.light;ctx.beginPath();ctx.ellipse(0,-39,10,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1b2724';ctx.beginPath();ctx.ellipse(-6,-46,2.4,3.2,0,0,7);ctx.ellipse(6,-46,2.4,3.2,0,0,7);ctx.fill();ctx.fillStyle='#fff9dc';ctx.beginPath();ctx.arc(-6.6,-47,0.8,0,7);ctx.arc(5.4,-47,0.8,0,7);ctx.fill();ctx.fillStyle=d.dark;ctx.beginPath();ctx.arc(0,-40,1.8,0,7);ctx.fill();ctx.strokeStyle=d.dark;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(0,-37,3,0.2,2.9);ctx.stroke();
// characteristic crest, magic orb or shell
if(s==='stoneback'){ctx.fillStyle='#c2bb91';ctx.beginPath();ctx.moveTo(-16,-32);ctx.quadraticCurveTo(-22,-55,-4,-57);ctx.quadraticCurveTo(20,-60,18,-34);ctx.closePath();ctx.fill();ctx.strokeStyle='#878772';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-8,-53);ctx.lineTo(-3,-34);ctx.moveTo(6,-55);ctx.lineTo(4,-34);ctx.stroke()}else if(s==='emberfox'||s==='glimmerling'||s==='moonhare'){ctx.fillStyle=s==='emberfox'?'#f5aa5e':s==='moonhare'?'#e7e4ff':'#f3d37b';ctx.shadowColor=d.light;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(0,-67,4,0,7);ctx.fill();ctx.shadowBlur=0}else if(s==='mossling'||s==='thornhorn'){ctx.fillStyle='#8caa63';ctx.beginPath();ctx.ellipse(0,-59,5,9,0,0,7);ctx.fill();ctx.beginPath();ctx.ellipse(-5,-57,4,7,-.6,0,7);ctx.ellipse(5,-57,4,7,.6,0,7);ctx.fill()}else{ctx.strokeStyle=d.light;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-60,7,.2,2.9);ctx.stroke()}
// glowy combat tell
if(fighting&&unit?.heal){ctx.globalAlpha=.7+Math.sin(clock*9)*.3;ctx.strokeStyle='#95eeb5';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-37,31+Math.sin(clock*6)*2,0,7);ctx.stroke();unit.heal=Math.max(0,unit.heal-.04);ctx.globalAlpha=1}
ctx.restore();if(big||fighting){let hp=Math.max(0,unit?.hp??unit?.max??100),max=unit?.max??100,w=43,barY=y-94*sz;ctx.fillStyle='#0c1312c9';rr(x-w/2-2,barY-2,w+4,7,3);ctx.fill();ctx.fillStyle='#3c4b3b';rr(x-w/2,barY,w,3,2);ctx.fill();ctx.fillStyle=isAlly?'#79c994':'#da7961';rr(x-w/2,barY,w*Math.max(0,hp/max),3,2);ctx.fill();ctx.font='700 8px DM Sans';ctx.textAlign='center';ctx.fillStyle='#f5ecd4';ctx.fillText(big?'GROVE SENTINEL':species[s].name.toUpperCase(),x,barY-5);if(unit?.hit){ctx.fillStyle=isAlly?'#ff8b6b':'#ffce75';ctx.font='bold 13px DM Sans';ctx.fillText(isAlly?'−':'−'+Math.ceil((24+wave*4)),x+15,y-89)}}}
function animate(){draw();requestAnimationFrame(animate)}
function init(){deal();render();resize();new ResizeObserver(resize).observe(canvas);animate()}
init();

