const $=s=>document.querySelector(s),canvas=$('#arena'),ctx=canvas.getContext('2d');
const species={mossling:{name:'Mossling',role:'Healer',color:'#87ba82',light:'#c5d690',dark:'#466c52',type:'heal',mark:'✚',rarity:'UNCOMMON'},emberfox:{name:'Emberfox',role:'Arcane striker',color:'#e68a5b',light:'#ffd18a',dark:'#9c4938',type:'magic',mark:'✦',rarity:'RARE'},stoneback:{name:'Stoneback',role:'Guardian tank',color:'#a7a78a',light:'#e4d7a1',dark:'#55584e',type:'tank',mark:'⬟',rarity:'COMMON'},sylphkin:{name:'Sylphkin',role:'Windweaver',color:'#81b9bd',light:'#c7eee2',dark:'#4e7181',type:'buff',mark:'⌁',rarity:'RARE'},thornhorn:{name:'Thornhorn',role:'Wild bruiser',color:'#b8a06a',light:'#eadca0',dark:'#697347',type:'physical',mark:'✧',rarity:'COMMON'},moonhare:{name:'Moonhare',role:'Dream mage',color:'#aab6d3',light:'#e6e5ff',dark:'#68738d',type:'magic',mark:'☾',rarity:'EPIC'},glimmerling:{name:'Glimmerling',role:'Dawn healer',color:'#dcad64',light:'#fff0af',dark:'#94714a',type:'heal',mark:'✦',rarity:'RARE'},duskwing:{name:'Duskwing',role:'Sky sentinel',color:'#ae8fc4',light:'#e0c8ff',dark:'#63527e',type:'buff',mark:'⌁',rarity:'EPIC'}};
let owned=[{id:1,s:'mossling',level:2},{id:2,s:'emberfox',level:1},{id:3,s:'stoneback',level:1},{id:4,s:'sylphkin',level:1}],team=[],gold=42,wave=1,shop=[],fighting=false,speed=1,sorted=false,gameState={round:1,effects:[],winner:null,units:[]},nextId=5;
function icon(s){let d=species[s];return `<svg class="pet-art" viewBox="0 0 64 72" aria-hidden="true"><ellipse cx="32" cy="66" rx="19" ry="4" fill="#070b0b" opacity=".55"/><path d="M14 53 Q7 58 12 62 Q20 63 23 55 M43 55 Q47 63 53 60 Q56 55 48 51" fill="${d.dark}"/><ellipse cx="32" cy="49" rx="19" ry="17" fill="${d.dark}"/><ellipse cx="31" cy="45" rx="16" ry="16" fill="${d.color}"/><ellipse cx="31" cy="50" rx="11" ry="9" fill="${d.light}" opacity=".78"/><path d="M18 34 Q12 18 20 20 Q27 22 28 33 M38 32 Q45 14 51 20 Q53 27 44 38" fill="${d.color}" stroke="${d.dark}" stroke-width="2"/><ellipse cx="31" cy="33" rx="15" ry="14" fill="${d.color}"/><ellipse cx="26" cy="34" rx="2.3" ry="3" fill="#192321"/><ellipse cx="38" cy="34" rx="2.3" ry="3" fill="#192321"/><circle cx="25.4" cy="33" r=".8" fill="white"/><circle cx="37.4" cy="33" r=".8" fill="white"/><path d="M29 40 Q32 42 35 40" fill="none" stroke="${d.dark}" stroke-width="1.5" stroke-linecap="round"/><path d="M19 30 Q31 23 44 30" fill="none" stroke="${d.light}" stroke-width="2" opacity=".6"/><circle cx="48" cy="16" r="5" fill="${d.light}" opacity=".8"/><text x="48" y="19" text-anchor="middle" font-size="7" fill="${d.dark}">${d.mark}</text></svg>`}
function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),1550)}
function baseHp(p){return (p.s==='stoneback'?150:100)+p.level*12}function baseAtk(p){return (p.s==='stoneback'?14:p.s==='mossling'?17:p.s==='sylphkin'?18:p.s==='emberfox'?32:24)+p.level*4}function price(s){return s.cost||18}
function petCard(p){let d=species[p.s],inTeam=team.includes(p.id);return `<div class="pet-card ${inTeam?'selected':''}" draggable="true" data-id="${p.id}">${icon(p.s)}<div class="pet-details"><div class="pet-name-line"><span class="pet-name">${d.name}</span><span class="rarity">${d.rarity}</span></div><div class="pet-role">${d.role}</div><div class="pet-stats"><span>❤ <b>${baseHp(p)}</b></span><span>✦ <b>${baseAtk(p)}</b></span><span>◈ <b>${p.level}</b></span></div></div><span class="pet-action">${d.type==='heal'?'HEALS':d.type==='tank'?'TANK':d.type==='buff'?'BUFF':d.type==='magic'?'MAGIC':'STRIKES'}</span><span class="pet-lvl">LV. ${p.level}</span></div>`}
function deal(){let pool=['thornhorn','glimmerling','moonhare','duskwing','emberfox','mossling','stoneback','sylphkin'];shop=Array.from({length:4},()=>{let s=pool[Math.floor(Math.random()*pool.length)];return {s,cost:s==='moonhare'||s==='duskwing'?28:s==='thornhorn'||s==='stoneback'?15:20}});render()}
function render(){$('#gold').textContent=gold;$('#wave').textContent=String(wave).padStart(2,'0');$('#teamCount').textContent=`${team.length} / 3`;$('#ownedCount').textContent=String(owned.length).padStart(2,'0');$('#foePower').textContent=250+wave*90;$('#roundNumber').textContent=gameState.round;$('#roster').innerHTML=(sorted?[...owned].sort((a,b)=>species[a.s].name.localeCompare(species[b.s].name)):owned).map(petCard).join('');$('#teamSlots').innerHTML=Array.from({length:3},(_,i)=>{let p=owned.find(x=>x.id===team[i]);if(!p)return `<div class="team-slot" data-slot="${i}"><div class="slot-empty"><strong>＋</strong>OPEN SLOT ${i+1}</div></div>`;let d=species[p.s];return `<div class="team-slot filled" data-slot="${i}">${icon(p.s)}<div class="slot-info"><b>${d.name}</b><small>${d.role} · LV.${p.level}</small></div><button class="remove-slot" data-remove="${i}" aria-label="Remove pet">×</button></div>`}).join('');$('#shopList').innerHTML=shop.map((item,i)=>{let d=species[item.s];return `<div class="shop-item ${item.sold?'sold':''}" data-buy="${i}">${icon(item.s)}<div class="shop-info"><div class="shop-name">${d.name}</div><div class="shop-desc">${d.role}</div><span class="shop-price">◈ ${price(item)}</span></div></div>`}).join('');let status=$('.battle-status');status.innerHTML=fighting?'<i></i> COMPANIONS IN COMBAT':gameState.winner?`<i></i> ${gameState.winner==='win'?'VICTORY — ENCOUNTER CLEARED':'DEFEAT — REGROUP AND TRY AGAIN'}`:'<i></i> PREPARE YOUR FORMATION';status.classList.toggle('fighting',fighting);$('#battleText').textContent=fighting?'BATTLE IN PROGRESS':gameState.winner?gameState.winner==='win'?'CLAIM VICTORY':'TRY AGAIN':'START BATTLE';$('#battleBtn').disabled=fighting;$('#battleBtn').className='battle-btn'+(gameState.winner==='win'?' victory':gameState.winner==='lose'?' defeat':'')}
// APPEND

