function buy(i){let item=shop[i];if(!item||item.sold)return;if(gold<price(item)){showToast('Not enough gold');return}if(owned.length>=12){showToast('Compendium is full');return}gold-=price(item);item.sold=true;owned.push({id:nextId++,s:item.s,level:1});showToast(`${species[item.s].name} joined your compendium!`);render()}
$('#roster').addEventListener('click',e=>{let c=e.target.closest('.pet-card');if(c)toggleTeam(+c.dataset.id)});$('#roster').addEventListener('dragstart',e=>{let c=e.target.closest('.pet-card');if(c)e.dataTransfer.setData('pet',c.dataset.id)});$('#teamSlots').addEventListener('click',e=>{let r=e.target.closest('[data-remove]');if(r){team.splice(+r.dataset.remove,1);render();draw()}});$('#teamSlots').addEventListener('dragover',e=>{if(e.target.closest('.team-slot')){e.preventDefault();e.target.closest('.team-slot').classList.add('drag-over')}});$('#teamSlots').addEventListener('dragleave',e=>e.target.closest('.team-slot')?.classList.remove('drag-over'));$('#teamSlots').addEventListener('drop',e=>{let sl=e.target.closest('.team-slot');if(sl){e.preventDefault();sl.classList.remove('drag-over');let id=+e.dataTransfer.getData('pet');if(id)toggleTeam(id,+sl.dataset.slot)}});$('#shopList').addEventListener('click',e=>{let c=e.target.closest('[data-buy]');if(c)buy(+c.dataset.buy)});
$('#rerollBtn').onclick=()=>{if(gold<3){showToast('Need 3 gold to reroll');return}gold-=3;deal();showToast('The merchant found fresh stock')};$('#sortBtn').onclick=()=>{sorted=!sorted;render()};$('#marketTab').onclick=()=>showToast('The travelling merchant is open below');$('#upgradeBtn').onclick=()=>{let p=owned.find(x=>team.includes(x.id))||owned[0];if(!p){showToast('Recruit a companion first');return}if(gold<15){showToast('Need 15 gold to strengthen a bond');return}gold-=15;p.level++;showToast(`${species[p.s].name} reached level ${p.level}!`);render();draw()};$('#resetBtn').onclick=()=>{if(fighting)return;team=[];gameState.winner=null;render();draw()};$('#speedBtn').onclick=()=>{speed=speed===1?2:1;$('#speedBtn').innerHTML=`Ⅱ <span>${speed}× SPEED</span>`};$('#battleBtn').onclick=()=>{if(fighting)return;if(gameState.winner==='win'){gameState.winner=null;render();return}if(team.length===0){showToast('Choose at least one companion');return}startBattle()};
function toggleTeam(id,slot){if(fighting)return;let idx=team.indexOf(id);if(idx>=0){team.splice(idx,1)}else if(team.length<3){if(slot!=null&&slot<team.length)team.splice(slot,0,id);else team.push(id)}else{showToast('Your formation is full');return}render();draw()}
function startBattle(){fighting=true;gameState.winner=null;gameState.round=1;gameState.effects=[];gameState.units=team.map(id=>{let p=owned.find(x=>x.id===id);return {p,hp:baseHp(p),max:baseHp(p),hit:0,heal:0}});gameState.enemyHp=260+wave*76;gameState.enemyMax=gameState.enemyHp;gameState.enemyHit=0;render();battleTick();clearInterval(gameState.timer);gameState.timer=setInterval(battleTick,1350/speed)}
function battleTick(){if(!fighting)return;const allies=gameState.units.filter(x=>x.hp>0);if(!allies.length){finish('lose');return}let damage=0,buff=allies.some(x=>x.p.s==='sylphkin'||x.p.s==='duskwing')?1.18:1;for(let u of allies){let s=u.p.s;if(s==='mossling'||s==='glimmerling'){let target=[...allies].sort((a,b)=>a.hp/a.max-b.hp/b.max)[0];target.hp=Math.min(target.max,target.hp+29+u.p.level*6);target.heal=1;continue}damage+=baseAtk(u.p)*buff*(s==='stoneback'?.8:s==='thornhorn'?1.35:1);u.hit=1}gameState.enemyHp-=damage;gameState.enemyHit=1;if(gameState.enemyHp<=0){finish('win');return}let target=allies.find(x=>x.p.s==='stoneback')||allies[Math.floor(Math.random()*allies.length)];target.hp-=24+wave*4;target.hit=1;if(target.hp<=0){target.hp=0;showToast(`${species[target.p.s].name} needs a breather`)}gameState.round++;render();if(gameState.units.every(x=>x.hp<=0)||gameState.round>11)finish('lose');draw()}
function finish(result){fighting=false;clearInterval(gameState.timer);gameState.winner=result;if(result==='win'){let reward=12+wave*2;gold+=reward;showToast(`VICTORY! +${reward} GOLD`);wave++}else showToast('Your party was overwhelmed. Try a new formation.');render();draw()}
// APPEND

