// A hand-painted isometric arena and toy-like creatures, drawn without external assets.
let W=0,H=0,dpr=1,clock=0;function resize(){let r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
